pub fn generated_contract_schema_json() -> Result<String, serde_json::Error> {
    let schema = schema_for!(LibraryBoundaryContract);
    let mut output = String::new();
    output.push_str(&serde_json::to_string_pretty(&schema)?);
    output.push('\n');
    Ok(output)
}

pub const fn protocol_crate_name() -> &'static str {
    env!("CARGO_PKG_NAME")
}

pub const fn protocol_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

fn push_ts_decl<T>(cfg: &Config, output: &mut String)
where
    T: TS,
{
    output.push_str("export ");
    output.push_str(&T::decl(cfg));
    output.push_str("\n\n");
}

#[cfg(test)]
mod tests {
    use super::{generated_contract_index_ts, generated_contract_schema_json};

    #[test]
    fn generated_typescript_exports_outer_contract_and_protocol_error() {
        let ts = generated_contract_index_ts();

        assert!(ts.contains("export type CommandRequest"));
        assert!(ts.contains("export type CommandOutcome"));
        assert!(ts.contains("export type ProtocolError"));
        assert!(ts.contains("registerLocalRoot"));
        assert!(ts.contains("startRootScan"));
        assert!(ts.contains("readLocalRoots"));
        assert!(ts.contains("unregisterLocalRoot"));
        assert!(ts.contains("readSourceLifecycle"));
        assert!(ts.contains("SourceLifecycle"));
        assert!(ts.contains("readLibraryTreeChildren"));
        assert!(ts.contains("LibraryTreeNode"));
        assert!(ts.contains("LibraryTreeFileClass"));
        assert!(ts.contains("fileClass: ContentsFileClass"));
        assert!(ts.contains("playableMediaBrowse"));
        assert!(ts.contains("hasPolicyOmittedRows: boolean"));
        assert!(!ts.contains(&["media", "Class"].concat()));
        assert!(!ts.contains(&["Contents", "Media", "Class"].concat()));
        assert!(ts.contains("DirectoryPrimaryMediaState"));
        assert!(ts.contains("DirectoryImageMediaState"));
        assert!(ts.contains("DirectoryScanState"));
        assert!(ts.contains("readNavigationNodeLibraryBrowserWindow"));
        assert!(ts.contains("searchNavigationNodeLibraryBrowserWindow"));
        assert!(ts.contains("readLibraryAssetPreparationDetail"));
        assert!(ts.contains("acceptTrackIdentityCandidate"));
        assert!(ts.contains("TrackIdentityDecisionCommand"));
        assert!(ts.contains("LibraryAssetPreparationDetailGroupKey"));
        assert!(!ts.contains("readLibraryBrowserWindow"));
        assert!(!ts.contains("searchLibraryBrowserWindow"));
        assert!(ts.contains("navigationRowId: string"));
        assert!(ts.contains("rowVersion: string"));
    }

    #[test]
    fn generated_typescript_exports_typed_search_filter_status_fields() {
        let ts = generated_contract_index_ts();

        assert!(ts.contains("export type SearchFilterIndexState"));
        assert!(ts.contains("export type SearchFilterAuthorityLayer"));
        assert!(ts.contains("export type SearchFilterEvidenceCoverageState"));
        assert!(ts.contains("export type SearchFilterMatchReason"));
        assert!(ts.contains("indexState: SearchFilterIndexState"));
        assert!(ts.contains("authorityLayer: SearchFilterAuthorityLayer"));
        assert!(ts.contains("attachmentLinkState: SearchFilterAttachmentLinkState"));
        assert!(ts.contains("evidenceCoverageState: SearchFilterEvidenceCoverageState"));
        assert!(ts.contains("matchReason: SearchFilterMatchReason"));
        assert!(ts.contains("\"notApplicable\""));
        assert!(ts.contains("\"partial\""));
    }

    #[test]
    fn generated_schema_exports_outer_contract_and_protocol_error() {
        let schema = generated_contract_schema_json().expect("generate schema");

        assert!(schema.contains("\"CommandRequest\""));
        assert!(schema.contains("\"CommandOutcome\""));
        assert!(schema.contains("\"ProtocolError\""));
        assert!(schema.contains("\"registerLocalRoot\""));
        assert!(schema.contains("\"readSourceLifecycle\""));
        assert!(schema.contains("\"readLibraryTreeChildren\""));
        assert!(schema.contains("\"fileClass\""));
        assert!(schema.contains("\"playableMediaBrowse\""));
        assert!(schema.contains("\"hasPolicyOmittedRows\""));
        assert!(!schema.contains(&format!("\"{}\"", ["media", "Class"].concat())));
        assert!(!schema.contains(&format!("\"{}\"", ["Contents", "Media", "Class"].concat())));
        assert!(schema.contains("\"acceptTrackIdentityCandidate\""));
        assert!(schema.contains("\"protocolError\""));
        assert!(schema.contains("\"navigationRowId\""));
        assert!(schema.contains("\"type\": \"string\""));
    }
}
